def k_machine_schedule(jobs: list[list[int]], k: int) -> int:
    if not jobs:
        return 0

    from heapq import heappop, heappush

    times = sorted({t for start, end, _ in jobs for t in (start, end)})
    index = {t: i for i, t in enumerate(times)}
    n = len(times)
    graph = [[] for _ in range(n)]

    def add_edge(u: int, v: int, capacity: int, cost: int) -> None:
        graph[u].append([v, len(graph[v]), capacity, cost])
        graph[v].append([u, len(graph[u]) - 1, 0, -cost])

    for i in range(n - 1):
        add_edge(i, i + 1, k, 0)

    for start, end, pay in jobs:
        add_edge(index[start], index[end], 1, -pay)

    inf = 10**30
    potential = [inf] * n
    potential[0] = 0

    # Initially, every edge with positive capacity points forward in time.
    for u in range(n):
        for v, _, capacity, cost in graph[u]:
            if capacity and potential[v] > potential[u] + cost:
                potential[v] = potential[u] + cost

    total_cost = 0
    remaining = k

    while remaining:
        dist = [inf] * n
        dist[0] = 0
        previous = [None] * n
        heap = [(0, 0)]

        while heap:
            current_dist, u = heappop(heap)
            if current_dist != dist[u]:
                continue

            for edge_index, (v, _, capacity, cost) in enumerate(graph[u]):
                if capacity:
                    new_dist = current_dist + cost + potential[u] - potential[v]
                    if new_dist < dist[v]:
                        dist[v] = new_dist
                        previous[v] = (u, edge_index)
                        heappush(heap, (new_dist, v))

        for i in range(n):
            if dist[i] < inf:
                potential[i] += dist[i]

        flow = remaining
        v = n - 1
        while v:
            u, edge_index = previous[v]
            flow = min(flow, graph[u][edge_index][2])
            v = u

        v = n - 1
        while v:
            u, edge_index = previous[v]
            edge = graph[u][edge_index]
            total_cost += flow * edge[3]
            edge[2] -= flow
            graph[v][edge[1]][2] += flow
            v = u

        remaining -= flow

    return -total_cost
